// =====================================================================================
//  IDOLVERSE48: Select Bloom! — Documentaries (watch the real history of your group)
// -------------------------------------------------------------------------------------
//  A viewing feature, not a management system: pick a category, the game builds the film from the save.
//  · Categories: Group (the whole history, then continued from where the last one ended), Member, Election, Graduation.
//  · Everything comes from saved records: auditions & generations, debut, every single (Senbatsu, Centers, Under
//    Girls, costumes), elections, concerts, Theater Stages, roadshows, captains, awards, relationships, graduations.
//  · Continuity: S.doc keeps every event / story / interview already used and the coverage period of each
//    category, so a new documentary only tells what happened since — old events are only recalled briefly.
//    Nothing is generated when there is not enough new material.
//  · Pictures are drawn from the event itself with the game's own art: single stages / MV / covers in THAT single's
//    costumes, election photos, concert and Theater stages, rehearsal scenes in practice wear (cz-practice.js);
//    interviews are recorded in the CURRENT single costume. Backgrounds: js/art/doc-bg.js.
//  · Only scene descriptions are saved; pictures are drawn when watching.
// =====================================================================================
const DC_T=(en,th)=>(typeof UIP!='undefined'&&UIP.lang=='th')?th:en;
const DC_TH=()=>typeof UIP!='undefined'&&UIP.lang=='th';
function dcS(){if(!S)return null;if(!S.doc||typeof S.doc!='object')S.doc={v:1,seq:0,list:[],used:{ev:{},st:{},iv:{}},cov:{}};const D=S.doc;D.list=Array.isArray(D.list)?D.list:[];D.used=D.used||{};['ev','st','iv'].forEach(k=>{if(!D.used[k]||typeof D.used[k]!='object')D.used[k]={}});D.cov=D.cov||{};return D}
const dcHash=s=>{let h=2166136261;for(const c of String(s))h=Math.imul(h^c.charCodeAt(0),16777619);return h>>>0};
const dcPick=(arr,seed)=>arr[dcHash(seed)%arr.length];
const dcYear=d=>{try{return dayDate(d).getFullYear()}catch(e){return 2026}};
const dcMem=id=>get(id)||(S.alumni||[]).find(m=>m.id==id)||null;
const dcNm=id=>{const m=dcMem(id);return m?m.name:'?'};
const dcFirst=id=>{const m=dcMem(id);return m?String(m.name).split(' ')[0]:'?'};
const dcList=(ids,n=4)=>{const L=ids.map(dcNm).slice(0,n);return L.length<=1?L.join(''):L.slice(0,-1).join(', ')+(DC_TH()?' และ ':' and ')+L.at(-1)};
// ---- 1. history from the save (current group) ------------------------------------------------------------------------------------
function dcGroupMembers(gid){return[...S.members,...(S.alumni||[])].filter(m=>m&&(m.group==gid||(typeof gsGid=='function'&&gsGid(m)==gid)))}
function dcEvents(gid){const g=grp(gid)||S.groups[0],E=[],add=e=>{if(e&&e.day!=null&&isFinite(e.day))E.push(e)};const MS=dcGroupMembers(gid);
 add({id:`form:${gid}`,day:g.formed??g.founded??0,k:'form',maj:1});
 (S.auds||[]).filter(a=>a.done&&(a.gid==null||a.gid==gid)).forEach(a=>{const ids=MS.filter(m=>(m.gen||1)==(a.gen||1)&&Math.abs((m.joined??0)-a.day)<=45).map(m=>m.id);add({id:`aud:${a.id}`,day:a.day,k:'aud',gen:a.gen||1,n:(a.cands||[]).length,ids,maj:1})});
 const gens={};MS.forEach(m=>{const k=m.gen||1;(gens[k]=gens[k]||[]).push(m)});Object.entries(gens).forEach(([k,L])=>add({id:`gen:${gid}:${k}`,day:Math.min(...L.map(m=>m.joined??0)),k:'gen',gen:+k,ids:L.map(m=>m.id),maj:1}));
 if(g.debutDay!=null)add({id:`debut:${gid}`,day:g.debutDay,k:'debut',maj:1});
 (S.singles||[]).forEach((x,i)=>{if(!x.mainId)return;const o=S.songs[x.mainId];if(!o)return;const ids=(o.slots||[]).filter(Boolean),cen=(o.centers&&o.centers.length?o.centers:o.center!=null?[o.center]:[]);
  const day=x.relDay??x.day,act=MS.filter(m=>(m.joined??0)<day&&!(m.dep&&m.dep.day<day)).map(m=>m.id),under=act.filter(id=>!ids.includes(id));
  if(x.ann&&x.ann.day!=null)add({id:`ann:${x.rid}`,day:x.ann.day,k:'ann',rid:x.rid,maj:0});
  add({id:`sg:${x.rid}`,day,k:x.kind=='album'?'album':'single',rid:x.rid,num:x.num,ids,cen,under,maj:1})});
 try{(typeof srxS=='function'?srxS().list:[]).filter(z=>z.st=='released'&&z.rec).forEach(z=>add({id:`sp:${z.id}`,day:z.rec.relDay??z.rec.day,k:'special',sx:z.id,maj:1}))}catch(e){}
 try{(geS().list||[]).filter(e=>e.st=='done'&&e.final&&e.final.rows).forEach(e=>add({id:`ge:${e.id}`,day:e.final.day??e.doneDay??e.vEnd,k:'ge',eid:e.id,maj:1}))}catch(e){}
 try{ccS().list.filter(C=>C.status=='done'&&(C.host==null||C.host==gid)).forEach(C=>{const L=(C.pf||[]).filter(p=>p.res);const d=L.length?Math.max(...L.map(p=>p.day)):C.start;add({id:`cc:${C.id}`,day:d,k:'concert',cid:C.id,maj:1})})}catch(e){}
 try{Object.values(thS().st||{}).filter(s=>s.debut!=null&&!s.gst).forEach(s=>add({id:`st:${s.id}`,day:s.debut,k:'stage',sid:s.id,maj:s.no==1?1:0}))}catch(e){}
 try{const Y={};Object.values(S.rs&&S.rs.hist||{}).flat().forEach(h=>{if(!h||h.day==null)return;const y=dcYear(h.day);(Y[y]=Y[y]||[]).push(h)});Object.entries(Y).forEach(([y,L])=>{const end=Math.max(...L.map(h=>h.day));if(L.length>=3)add({id:`rs:${gid}:${y}`,day:end,k:'tour',year:+y,n:L.length,locs:[...new Set(L.map(h=>h.loc||h.locName||''))].filter(Boolean).slice(0,4),maj:0})})}catch(e){}
 MS.forEach(m=>(m.mh||[]).forEach(e=>{if(e.t=='cap'||e.t=='cap_start')add({id:`cap:${m.id}:${e.day}`,day:e.day,k:'captain',mid:m.id,maj:0});if(e.t=='award')add({id:`aw:${m.id}:${e.day}`,day:e.day,k:'award',mid:m.id,txt:e.name||e.title||e.aw||'',maj:0})}));
 MS.filter(m=>m.dep&&m.dep.kind=='grad'&&m.dep.day!=null).forEach(m=>add({id:`grad:${m.id}`,day:m.dep.day,k:'grad',mid:m.id,maj:1}));
 return E.sort((a,b)=>a.day-b.day||(a.k=='form'?-1:b.k=='form'?1:0))}
// popularity stories for a period: biggest rise of Kami Oshi fans, and members who keep missing out
function dcPopStories(gid,from,to){const out=[],H=(S.fb&&S.fb.hist)||[],act=S.members.filter(m=>m.group==gid&&isAct(m));if(!act.length)return out;
 try{const A=H.filter(h=>h.day>from&&h.day<=to&&h.mem);if(A.length>=2){const a=A[0].mem,b=A.at(-1).mem;const R=act.map(m=>[m,((b[m.id]||[0])[0]||0)-((a[m.id]||[0])[0]||0)]).filter(x=>x[1]>0).sort((x,y)=>y[1]-x[1]);if(R[0])out.push({id:`rise:${R[0][0].id}:${dcYear(to)}`,day:to,k:'rise',mid:R[0][0].id,gain:R[0][1],maj:0})}}catch(e){}
 const st=act.filter(m=>(m.joined??0)<to-180&&m.senRec&&(m.senRec.sel|0)==0).sort((a,b)=>(a.joined??0)-(b.joined??0))[0]||act.filter(m=>m.senRec&&(m.senRec.consNone|0)>=3).sort((a,b)=>(b.senRec.consNone|0)-(a.senRec.consNone|0))[0];
 if(st)out.push({id:`strug:${st.id}:${dcYear(to)}`,day:to,k:'struggle',mid:st.id,n:st.senRec?st.senRec.consNone|0:0,maj:0});return out}
// ---- 2. narration (English · Thai), only facts from the records --------------------------------------------------------------------
const DC_N={
 form:e=>{const g=grp(e.gid);return[[`${jd(e.day)}. ${g.name} is founded. There are no songs, no fans and no stage yet — only a name and a promise.`,`${jd(e.day)} — ${g.name} ถือกำเนิดขึ้น ยังไม่มีเพลง ยังไม่มีแฟน ยังไม่มีเวที มีเพียงชื่อและคำสัญญา`],[`It begins quietly. On ${jd(e.day)}, ${g.name} exists for the first time.`,`ทุกอย่างเริ่มต้นอย่างเงียบ ๆ วันที่ ${jd(e.day)} ${g.name} ได้ถือกำเนิดขึ้นเป็นครั้งแรก`]]},
 aud:e=>[[`The ${ordN(e.gen)} generation audition: ${e.n} girls walk into the room. ${e.ids.length} of them walk out as members.`,`ออดิชันรุ่นที่ ${e.gen}: เด็กสาว ${e.n} คนเดินเข้าห้อง และมี ${e.ids.length} คนที่เดินออกมาในฐานะสมาชิก`],[`${e.n} applicants, one room, a few minutes each. The ${ordN(e.gen)} generation is chosen.`,`ผู้สมัคร ${e.n} คน ห้องเดียว คนละไม่กี่นาที — สมาชิกรุ่นที่ ${e.gen} ถูกเลือกแล้ว`]],
 gen:e=>[[`The ${ordN(e.gen)} generation — ${e.ids.length} members: ${dcList(e.ids,5)}${e.ids.length>5?' and more':''}.`,`รุ่นที่ ${e.gen} — สมาชิก ${e.ids.length} คน: ${dcList(e.ids,5)}${e.ids.length>5?' และคนอื่น ๆ':''}`]],
 debut:e=>{const g=grp(e.gid);return[[`${jd(e.day)}. ${g.name} debuts. The first stage is small, the lights are hot, and nobody knows what comes next.`,`${jd(e.day)} — ${g.name} เดบิวต์ เวทีแรกยังเล็ก แสงไฟร้อน และไม่มีใครรู้ว่าอนาคตจะเป็นอย่างไร`]]},
 ann:e=>{const x=dcSingle(e.rid);return x?[[`The Senbatsu for “${x.title}” is announced. Some names are called. Others are not.`,`ประกาศเซ็มบัตสึของ “${x.title}” บางชื่อถูกเรียก บางชื่อไม่ถูกเรียก`]]:null},
 single:e=>{const x=dcSingle(e.rid);if(!x)return null;const o=S.songs[x.mainId]||{},c=e.cen.map(dcNm);return[[`${x.num?ordN(x.num)+' single':'Single'}: “${x.title}” (${jd(e.day)}). ${c.length?`Center: ${c.join(' & ')}.`:''} ${e.ids.length} members in the Senbatsu, ${(x.sales||0).toLocaleString()} sold.`,`ซิงเกิลที่ ${x.num||''}: “${x.title}” (${jd(e.day)}) ${c.length?`เซ็นเตอร์: ${c.join(' และ ')}`:''} เซ็มบัตสึ ${e.ids.length} คน ยอดขาย ${(x.sales||0).toLocaleString()} แผ่น`],[`“${x.title}” — a ${String(o.concept||'').toLowerCase()} ${String(o.genre||'').toLowerCase()} song${c.length?`, with ${c.join(' and ')} at the Center`:''}.`,`“${x.title}” — เพลง${o.genre||''}แนว${o.concept||''}${c.length?` โดยมี ${c.join(' และ ')} ยืนเซ็นเตอร์`:''}`]]},
 album:e=>{const x=dcSingle(e.rid);return x?[[`The album “${String(x.title).replace(/^Album: /,'')}” collects the era in ${(x.tracks||[]).length||'many'} songs.`,`อัลบั้ม “${String(x.title).replace(/^Album: /,'')}” รวบรวมยุคนี้ไว้ใน ${(x.tracks||[]).length||''} เพลง`]]:null},
 under:e=>[[`Not everyone stands in the light. ${dcList(e.under.slice(0,4))} are outside the Title Track this time.`,`ไม่ใช่ทุกคนที่ได้ยืนกลางแสงไฟ ครั้งนี้ ${dcList(e.under.slice(0,4))} ไม่ได้อยู่ในเพลงหลัก`]],
 special:e=>{let z=null;try{z=srxGet(e.sx)}catch(x){}return z&&z.rec?[[`A special release, outside the numbered singles: “${z.rec.title}”.`,`งานพิเศษนอกลำดับซิงเกิล: “${z.rec.title}”`]]:null},
 ge:e=>{const E=geGet(e.eid);if(!E)return null;const R=E.final.rows.filter(r=>r.rank).sort((a,b)=>a.rank-b.rank),w=R[0];return[[`${E.name}. ${(E.final.tokens||E.tokens||0).toLocaleString()} votes. At the top: ${w?dcNm(w.id):'—'}.`,`${E.name} คะแนนโหวต ${(E.final.tokens||E.tokens||0).toLocaleString()} เสียง อันดับ 1: ${w?dcNm(w.id):'—'}`],[`The night of ${E.name}. Every name read aloud is a year of work. Number one: ${w?dcNm(w.id):'—'}.`,`คืนของ ${E.name} ทุกชื่อที่ถูกขานคือการทำงานตลอดทั้งปี อันดับ 1: ${w?dcNm(w.id):'—'}`]]},
 concert:e=>{const C=ccGet(e.cid);if(!C)return null;const L=(C.pf||[]).filter(p=>p.res),aud=L.reduce((a,p)=>a+((p.res&&p.res.phys)||(p.res&&p.res.att)||0),0);return[[`${C.name}. ${L.length} performance(s)${aud?`, ${aud.toLocaleString()} people in the venue`:''}.`,`${C.name} แสดง ${L.length} รอบ${aud?` ผู้ชมในฮอลล์ ${aud.toLocaleString()} คน`:''}`]]},
 stage:e=>{const s=thS().st[e.sid];if(!s)return null;return[[`Theater: ${s.no?ordN(s.no)+' Stage ':''}“${s.name}” (${thLabel(s.k)}) opens on ${jd(e.day)}${s.perfs?` and runs ${s.perfs} times`:''}.`,`เธียเตอร์: ${s.no?'สเตจที่ '+s.no+' ':''}“${s.name}” (${thLabel(s.k)}) เปิดการแสดงวันที่ ${jd(e.day)}${s.perfs?` แสดงทั้งหมด ${s.perfs} รอบ`:''}`]]},
 tour:e=>[[`On the road in ${e.year}: ${e.n} roadshow stops${e.locs.length?' — '+e.locs.join(', '):''}.`,`ออกเดินสายในปี ${e.year}: โรดโชว์ ${e.n} จุด${e.locs.length?' — '+e.locs.join(', '):''}`]],
 captain:e=>[[`${dcNm(e.mid)} is named captain.`,`${dcNm(e.mid)} ได้รับแต่งตั้งเป็นกัปตัน`]],
 award:e=>[[`${dcNm(e.mid)} receives an award${e.txt?': '+e.txt:''}.`,`${dcNm(e.mid)} ได้รับรางวัล${e.txt?': '+e.txt:''}`]],
 rise:e=>[[`Something changes for ${dcNm(e.mid)}: ${e.gain.toLocaleString()} more fans now call her their Kami Oshi.`,`บางอย่างเปลี่ยนไปสำหรับ ${dcNm(e.mid)}: มีแฟนเลือกเธอเป็นคามิโอชิเพิ่มขึ้น ${e.gain.toLocaleString()} คน`]],
 struggle:e=>[[`${dcNm(e.mid)} keeps practising${e.n?`, ${e.n} releases in a row without her name`:' and waiting for her name to be called'}.`,`${dcNm(e.mid)} ยังคงซ้อมต่อไป${e.n?` แม้ไม่มีชื่อติดต่อกัน ${e.n} ครั้ง`:' และรอวันที่ชื่อของเธอจะถูกเรียก'}`]],
 grad:e=>{const m=dcMem(e.mid);return m?[[`${jd(e.day)}. ${m.name} graduates${m.dep&&m.dep.stage?' after her Graduation Stage':''}.`,`${jd(e.day)} — ${m.name} จบการศึกษา${m.dep&&m.dep.stage?' หลังสเตจจบการศึกษาของเธอ':''}`]]:null}};
function dcSingle(rid){return(S.singles||[]).find(x=>x.rid==rid)||null}
function dcNarr(e,seed){const f=DC_N[e.k];if(!f)return null;const V=f({...e,gid:e.gid??gsAg()});if(!V||!V.length)return null;const D=dcS();let i=dcHash(seed+e.id)%V.length;for(let j=0;j<V.length;j++){const k=(i+j)%V.length;if(!D.used.st[e.id+'#'+k]){i=k;break}}D.used.st[e.id+'#'+i]=1;return{en:V[i][0],th:V[i][1]}}
