function dcPosterMembers(d){const gid=d.gid;if(d.cat=='mem'||d.cat=='grad')return[d.mid];if(d.cat=='ge'){const E=geGet((d.eids||[]).at(-1));return E?E.final.rows.filter(r=>r.rank).sort((a,b)=>a.rank-b.rank).slice(0,5).map(r=>r.id):[]}
 const L=S.members.filter(m=>(m.group==gid)&&isAct(m)).sort((a,b)=>b.pop-a.pop);const gens=[...new Set(L.map(m=>m.gen))];const pick=[];gens.forEach(g=>{const x=L.find(m=>m.gen==g&&!pick.includes(m));if(x)pick.push(x)});L.forEach(m=>{if(pick.length<7&&!pick.includes(m))pick.push(m)});return pick.slice(0,7).map(m=>m.id)}
function dcPosterSvg(d){const W=600,H=880,ids=dcPosterMembers(d),L=ids.map(dcMem).filter(Boolean),lay=d.cat=='group'?dcHash(d.id)%3:0;
 const bgk={group:['stage','auditorium','history'][lay],ge:'election',grad:'graduation',mem:['iv_key','theater','bw'][dcHash(d.id)%3]}[d.cat],bg=DOCBG.svg(bgk,d.seed).replace(/^<svg[^>]*>/,'').replace(/<\/svg>$/,'');
 let figs='';if(d.cat=='group'){const n=L.length;L.forEach((m,i)=>{const s=n>5?2.1:2.5,cx=W/2+(i-(n-1)/2)*(W/Math.max(n,1))*.95,y=H-200*s-150+(Math.abs(i-(n-1)/2)*16);figs+=`<g transform="translate(${(cx-50*s).toFixed(0)} ${y.toFixed(0)}) scale(${s})">${dcFig(m,{cd:dcCzCur(d,m.id),pose:0})}</g>`})}
 else if(d.cat=='ge'){L.forEach((m,i)=>{const s=i==0?3:1.9,cx=i==0?W/2:W/2+(i%2?-1:1)*(120+Math.floor((i-1)/2)*110),y=i==0?260:420+Math.floor((i-1)/2)*30;figs=(i==0?'':`<g opacity=".85" transform="translate(${(cx-50*s).toFixed(0)} ${y}) scale(${s})">${dcFig(m,{cd:dcCzCur(d,m.id)})}</g>`)+figs+(i==0?`<g transform="translate(${(cx-50*s).toFixed(0)} ${y}) scale(${s})">${dcFig(m,{cd:dcCzCur(d,m.id)})}</g><path d="M270 236L285 206L300 226L310 198L320 226L335 206L350 236Z" fill="#ffd98a"/>`:'')})}
 else{const m=L[0];if(m)figs=`<g transform="translate(${d.cat=='grad'?140:60} 180) scale(${d.cat=='grad'?3.2:4})">${dcFig(m,{cd:dcCzCur(d,m.id),ex:d.cat=='grad'?1:2})}</g>`}
 const t=d.title.en,big=t.split(' — ')[0],sub=t.includes(' — ')?t.split(' — ')[1]:'',cat={group:'A DOCUMENTARY OF '+d.gname.toUpperCase(),ge:'ELECTION DOCUMENTARY',grad:'GRADUATION DOCUMENTARY',mem:'MEMBER DOCUMENTARY'}[d.cat];
 const words=big.split(' ');const lines=[];let cur='';words.forEach(w=>{if((cur+' '+w).trim().length>14){lines.push(cur.trim());cur=w}else cur+=' '+w});if(cur.trim())lines.push(cur.trim());
 const ty=d.cat=='group'?120:d.cat=='ge'?110:H-250;
 return`<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}"><defs><linearGradient id="pf" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#000" stop-opacity=".55"/><stop offset=".35" stop-color="#000" stop-opacity="0"/><stop offset=".7" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".85"/></linearGradient></defs><svg x="-180" y="0" width="${W+360}" height="${H}" viewBox="0 0 1600 900" preserveAspectRatio="xMidYMid slice">${bg}</svg>${figs}<rect width="${W}" height="${H}" fill="url(#pf)"/>
 <text x="${W/2}" y="${ty-46}" font-size="15" letter-spacing="5" text-anchor="middle" fill="#e8d9b8" font-family="Quicksand,sans-serif" font-weight="700">${esc(cat)}</text>${lines.map((l,i)=>`<text x="${W/2}" y="${ty+i*58}" font-size="${lines.length>2?44:52}" text-anchor="middle" fill="#fbf4e6" font-family="'Shippori Mincho','Dela Gothic One',serif" font-weight="700" letter-spacing="2">${esc(l)}</text>`).join('')}${sub?`<text x="${W/2}" y="${ty+lines.length*58}" font-size="24" text-anchor="middle" fill="#ffd9e6" font-family="'Shippori Mincho',serif">${esc(sub)}</text>`:''}
 <text x="${W/2}" y="${H-40}" font-size="15" letter-spacing="3" text-anchor="middle" fill="#cbbfa8" font-family="Quicksand,sans-serif">${esc(d.gname)} · ${esc(String(dcYear(d.from)))}${dcYear(d.to)!=dcYear(d.from)?' – '+dcYear(d.to):''}</text><rect x="${W/2-60}" y="${H-70}" width="120" height="1" fill="#c9a86a"/></svg>`}
function dcPosterUrl(d){return d?dcUrl('po:'+d.id,()=>dcPosterSvg(d)):''}
